def summarize_low_stock_products(low_stock_products):
    """
    Summarizes low-stock product list.

    Args:
        low_stock_products (list): Low-stock product list.

    Returns:
        str: Summary of low-stock product list.
    """
    summary = f"Low-Stock Products Summary:\n"
    summary += f"Total low-stock products: {len(low_stock_products)}\n"
    summary += f"Total quantity: {sum(product['quantity'] for product in low_stock_products)}\n"
    return summary

